head.script:
// 마우스를 놓은 순간의 커서 X 좌표
scwin.mouseUpX = null;

scwin.onpageload = function () {
    document.addEventListener("mouseup", function (e) {
        scwin.mouseUpX = e.clientX;
    }, true);
};

// body CSS zoom 1.25 적용
scwin.btn_zoom_onclick = function (e) {
    document.body.style.zoom = "1.25";
    scwin.setReturnValue("[body zoom 1.25 적용]");
};

// body CSS zoom 해제
scwin.btn_reset_onclick = function (e) {
    document.body.style.zoom = "";
    scwin.setReturnValue("[body zoom 해제]");
};

// 드래그 완료 시 마우스 커서와 slider 버튼 중심의 가로 거리 출력
scwin.sld_test_onmovedone = function () {
    let sliderBtn = document.querySelector("#" + sld_test.id + "_thumb1").getBoundingClientRect();
    let gap = Math.round(sliderBtn.left + sliderBtn.width / 2 - scwin.mouseUpX);
    scwin.setReturnValue("마우스 커서와 slider 버튼 중심 거리 : " + gap + "px (body zoom : " + (document.body.style.zoom || "1") + ")");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
